import subprocess
import os
import logging
from taf.launcher.ue_proxy_mngr_fastmile.exceptions import FilePathError


class Shell(object):
    def __init__(self, logger=None):
        self.logger = logger or logging

    @staticmethod
    def _convert_bytes_to_str(data, encoding):
        if isinstance(data, bytes):
            data = data.decode(encoding=encoding)
        return data

    def execute(self, command, encoding='utf-8', **kwargs):
        """
        execute command through pipe

        :param command: command that user want to execute
        :type command: str
        :return pid : output after command execute
        """
        process = subprocess.Popen(command, stdout=subprocess.PIPE, shell=True)
        out = process.stdout.read()
        str_out = self._convert_bytes_to_str(out, encoding)
        self.logger.info(f'"{command}" output is "{str_out}".')
        return str_out

    def remove_file(self, file_path):
        if os.path.exists(file_path) and os.path.isfile(file_path):
            self.logger.warning(f'file "{file_path}" is exist, will be removed for recreation.')
            try:
                os.remove(file_path)
            except Exception as e:
                self.logger.warning(f"failed to remove local file {file_path} for {e}")
                return

            if os.path.exists(file_path) and os.path.isfile(file_path):
                raise FilePathError(f'failed to remove file "{file_path}".')

    def mkdir(self, dir_path):
        if os.path.exists(dir_path) and os.path.isdir(dir_path):
            return

        self.logger.info(f'"{dir_path}" is not exist, will be created.')
        os.makedirs(dir_path)
        if not os.path.exists(dir_path) or not os.path.isdir(dir_path):
            raise FilePathError('create folder "{}" failed, please check the folder if it is illegal.'.format(dir_path))
        self.logger.info(f'create folder "{dir_path}" successfully.')
